static QJsonArray strings(const ON_Object& object){QJsonArray result;ON_ClassArray<ON_UserString> values;object.GetUserStrings(values);for(int i=0;i<values.Count();++i)result.append(QJsonObject{{"key",text(values[i].m_key)},{"value",text(values[i].m_string_value)}});return result;}
