        for(int i=0;i<h->LoopCount();++i){auto loop=h->Loop(i);auto n=ON_NurbsCurve::Cast(loop->Curve());require(n,"modern exact native NURBS loop");QJsonArray cvs,knots;for(int j=0;j<n->CVCount();++j){QJsonArray cv;for(int k=0;k<n->CVSize();++k)cv.append(n->CV(j)[k]);cvs.append(cv);}for(int j=0;j<n->KnotCount();++j)knots.append(n->Knot(j));loops.append(QJsonObject{{"type",static_cast<int>(loop->Type())},{"class_name",n->ClassId()->ClassName()},{"dimension",n->Dimension()},{"order",n->Order()},{"rational",n->IsRational()},{"cvs",cvs},{"knots",knots},{"user_strings",strings(*n)}});}
        current["native_loops"]=hatchLoopInventory(*h);current["loops"]=loops;current["user_strings"]=strings(*h);current["attribute_user_strings"]=strings(*a);QJsonArray userdata;for(auto d=h->FirstUserData();d;d=d->Next())userdata.append(QJsonObject{{"class_uuid",id(d->ClassId()->Uuid())},{"userdata_uuid",id(d->m_userdata_uuid)}});current["userdata"]=userdata;hatches.append(current);
